import {Renderer as ClarityRenderer} from './clarity-renderer.js';
import {DISTRICTS,POINTS} from './district-data.js';
import {CROPS,WORLD} from './data.js';
export class Renderer extends ClarityRenderer{
 draw(e,mouse,dt=.016){if(e.d.track)this.rebuildTarget=e.districtTarget();super.draw(e,mouse,dt);}
 drawValleyPlot(p,e){const c=this.ctx;c.fillStyle=p.buffer?'#547965':e.valleyWatered(p)?'#624b35':'#94704c';c.fillRect(p.x-18,p.y-18,36,36);c.fillStyle=p.buffer?'#7ca981':'#b38c57';for(let i=0;i<4;i++)c.fillRect(p.x-15,p.y-14+i*8,30,2);if(p.crop){const ratio=p.growth/CROPS[p.crop].grow;this.sprite(ratio<.2?60:CROPS[p.crop].icon,p.x,p.y+14,ratio<.4?26:38,ratio<.4?28:44);if(ratio>=1)this.text('✦',p.x+14,p.y-26,'#f2d592',15);}this.valleyPlotLabel(p,e);}
 valleyPlotLabel(p,e){if(Math.hypot(p.x-e.s.player.x,p.y-e.s.player.y)<90){const c=this.ctx;c.strokeStyle='#e8d7a5';c.strokeRect(p.x-19,p.y-19,38,38);this.text(p.buffer?'净化带':p.crop?(e.valleyWatered(p)?'水✓':'缺水'):'空地',p.x,p.y+29,'#dfddba',10);}}
 drawDistrictBlock(r){const c=this.ctx;c.fillStyle=r.districtCrate?'#906443':'#756041';c.fillRect(r.x,r.y,r.w,r.h);c.strokeStyle='#c29964';c.lineWidth=3;c.strokeRect(r.x,r.y,r.w,r.h);for(let x=r.x+9;x<r.x+r.w;x+=18){c.fillStyle='#44392c';c.fillRect(x,r.y+7,4,r.h-14);}}
 drawRuins(e){if(!DISTRICTS[e.s.region])return super.drawRuins(e);const c=this.ctx,id=e.s.region;
  if(id==='valley'){for(const p of e.d.plots)this.drawValleyPlot(p,e);
   if(e.flag('watergate','built')){c.strokeStyle='#89b9b4';c.lineWidth=5;c.beginPath();c.moveTo(370,360);c.lineTo(e.point('watergate').choice==='lower'?1090:405,402);c.lineTo(e.point('watergate').choice==='lower'?1090:405,432);c.stroke();}}
  for(const r of e.colliders().filter(r=>r.districtBarrier||r.districtCrate))this.drawDistrictBlock(r);
  if(id==='stationMarket'){for(const [i,key]of ['food','repair','seed'].entries())if(e.flag('shops',key)){c.fillStyle=['#bea16b','#9caf98','#88995b'][i];c.fillRect(274+i*65,264,53,8);this.sprite([53,51,34][i],300+i*65,304,29,32);}if(e.flag('fund','lights'))for(const x of [530,830,1120]){c.fillStyle='#604b32';c.fillRect(x,660,5,48);c.fillStyle='#efd292';c.fillRect(x-5,650,15,16);}const t=this.time;for(let i=0;i<3;i++)this.sprite(i%2?56:57,650+Math.sin(t*.3+i)*85+i*130,630+(i%2)*35,42,56);}
  if(id==='quarantine'){const positions={lab:[960,360],ward:[370,730],sterile:[1260,360]};for(const [part,[x,y]]of Object.entries(positions)){c.strokeStyle=e.d.power.quarantine.includes(part)?'#d8c17a':'#586157';c.lineWidth=4;c.beginPath();c.moveTo(370,360);c.lineTo(x,y);c.stroke();}if(e.flag('corridor','vent')){c.fillStyle='#739e91';c.fillRect(550,325,280,8);}if(e.flag('evidence','solved')){c.fillStyle='#80bca3';c.fillRect(815,775,68,30);}}
  if(id==='railDepot'&&e.flag('switch','built')){const progress=(this.time*.06)%1,x=480+progress*650,y=e.point('switch').choice==='loading'?900:650;c.fillStyle='#a1764d';c.fillRect(x,y-24,74,28);c.fillStyle='#283a31';c.fillRect(x+8,y+4,13,8);c.fillRect(x+53,y+4,13,8);}
  if(e.d.noise?.region===id){c.strokeStyle='#e5c480';c.setLineDash([6,7]);c.lineWidth=2;c.beginPath();c.arc(e.d.noise.x,e.d.noise.y,65+Math.sin(this.time*5)*10,0,Math.PI*2);c.stroke();c.setLineDash([]);}
  if(id==='courtyard'&&e.flag('streetdefense','fence')){for(const x of [320,1160])this.sprite(46,x,830,90,38);}if(id==='courtyard'&&e.flag('streetdefense','trap'))for(const x of [300,1180])this.sprite(47,x,780,60,45);if(id==='courtyard'&&e.flag('streetdefense','tower'))this.atlas(7,960,780,60,110);
 }
 drawObject(o,e){if(o.type==='plot')return;if(['districtPoint','districtGate','districtStore','districtExit'].includes(o.type)){const c=this.ctx,near=Math.hypot(o.x-e.s.player.x,o.y-e.s.player.y)<140,active=o.pointId===e.d.track,done=o.pointId&&e.point(o.pointId).count>0;this.shadow(o.x,o.y,27);if(o.type==='districtPoint'){c.fillStyle=done?'#617850':'#65573a';c.fillRect(o.x-28,o.y-13,56,22);c.strokeStyle=done?'#c1cf98':'#9d8658';c.strokeRect(o.x-28,o.y-13,56,22);this.sprite(o.icon,o.x,o.y-5,48,53);c.fillStyle=active?'#edd197':done?'#a9c486':'#d5b17a';c.fillRect(o.x-6,o.y+15,12,5);if(near||active)this.badge(o.name,o.x,o.y-73,active?'#f5d894':'#e2dbc0');}else{this.sprite(o.type==='districtStore'?40:55,o.x,o.y,56,60);if(near)this.badge(o.name,o.x,o.y-73,'#edda9d');}return;}return super.drawObject(o,e);}
 drawMapPreview(canvas,e){super.drawMapPreview(canvas,e);if(!DISTRICTS[e.s.region])return;const c=canvas.getContext('2d');for(const p of POINTS.filter(p=>p.region===e.s.region)){const x=p.x/WORLD.w*768,y=p.y/WORLD.h*384;c.fillStyle=p.id===e.d.track?'#f7d090':e.point(p.id).count?'#b1da91':'#a9c8cd';c.fillRect(x-4,y-4,8,8);c.fillStyle='#ffefd1';c.font='12px sans-serif';if(p.id===e.d.track)c.fillText(p.name,x>570?x-130:x+8,y+4);}}
}
